51	export const localToUtc = (
52	  year: number,
53	  month: number,
54	  day: number,
55	  hour: number,
56	  minute: number,
57	  timeZone: string,
58	): number => {
59	  const targetLocalAsUtc = Date.UTC(year, month - 1, day, hour, minute, 0);
60	
61	  const getLocal = (utcMs: number) => {
62	    const dtf = new Intl.DateTimeFormat("en-US", {
63	      timeZone,
64	      year: "numeric",
65	      month: "2-digit",
66	      day: "2-digit",
67	      hour: "2-digit",
68	      minute: "2-digit",
69	      second: "2-digit",
70	      hour12: false,
71	    });
72	    const parts: Record<string, string> = {};
73	    for (const p of dtf.formatToParts(new Date(utcMs))) {
74	      parts[p.type] = p.value;
75	    }
76	    let h = parseInt(parts.hour ?? "0", 10);
77	    if (h === 24) h = 0;
78	    return {
79	      year: parseInt(parts.year ?? "0", 10),
80	      month: parseInt(parts.month ?? "0", 10),
81	      day: parseInt(parts.day ?? "0", 10),
82	      hour: h,
83	      minute: parseInt(parts.minute ?? "0", 10),
84	    };
85	  };
86	
87	  const toAsUtc = (l: { year: number; month: number; day: number; hour: number; minute: number }) =>
88	    Date.UTC(l.year, l.month - 1, l.day, l.hour, l.minute, 0);
89	
90	  const dayBeforeUtc = targetLocalAsUtc - 86_400_000;
91	  const dayAfterUtc = targetLocalAsUtc + 86_400_000;
92	  const offsetBefore = toAsUtc(getLocal(dayBeforeUtc)) - dayBeforeUtc;
93	  const offsetAfter = toAsUtc(getLocal(dayAfterUtc)) - dayAfterUtc;
94	
95	  const offsets = [offsetBefore, offsetAfter].sort((a, b) => b - a);
96	
97	  for (const offset of offsets) {
98	    const candidateUtc = targetLocalAsUtc - offset;
99	    if (toAsUtc(getLocal(candidateUtc)) === targetLocalAsUtc) {
100	      return candidateUtc;
101	    }
102	  }
103	
104	  const gap = Math.abs(offsetAfter - offsetBefore);
105	  const adjustedTargetAsUtc = targetLocalAsUtc + gap;
106	  return adjustedTargetAsUtc - offsetAfter;
107	};
