119	export const parseDateIso = (dateStr: string): { year: number; month: number; day: number } => {
120	  const parts = dateStr.split("-");
121	  const year = parseInt(parts[0] ?? "0", 10);
122	  const month = parseInt(parts[1] ?? "0", 10);
123	  const day = parseInt(parts[2] ?? "0", 10);
124	  return { year, month, day };
125	};
