130	export const parseSendTime = (sendTime: SendTime): { hour: number; minute: number } => {
131	  const parts = sendTime.split(":");
132	  const hour = parseInt(parts[0] ?? "0", 10);
133	  const minute = parseInt(parts[1] ?? "0", 10);
134	  return { hour, minute };
135	};
