137	export const nextWeekdayDate = (
138	  fromYear: number,
139	  fromMonth: number,
140	  fromDay: number,
141	  targetWeekday: Weekday,
142	  includeToday: boolean,
143	): string => {
144	  const date = new Date(Date.UTC(fromYear, fromMonth - 1, fromDay));
145	  const currentWeekday = date.getUTCDay();
146	  const targetDayNum = WEEKDAY_NUMBERS[targetWeekday];
147	
148	  let daysAhead = targetDayNum - currentWeekday;
149	  if (daysAhead < 0 || (daysAhead === 0 && !includeToday)) {
150	    daysAhead += 7;
151	  }
152	  const nextDate = new Date(date.getTime() + daysAhead * 86_400_000);
153	  return formatDateIso(nextDate.getUTCFullYear(), nextDate.getUTCMonth() + 1, nextDate.getUTCDate());
154	};
