156	export const nextEightWeeksCadenceDates = (
157	  nowMs: number,
158	  weekday: Weekday,
159	  timeZone: string,
160	): ReadonlyArray<string> => {
161	  const dtf = new Intl.DateTimeFormat("en-US", {
162	    timeZone,
163	    year: "numeric",
164	    month: "2-digit",
165	    day: "2-digit",
166	  });
167	  const parts: Record<string, string> = {};
168	  for (const p of dtf.formatToParts(new Date(nowMs))) {
169	    parts[p.type] = p.value;
170	  }
171	  const curYear = parseInt(parts.year ?? "0", 10);
172	  const curMonth = parseInt(parts.month ?? "0", 10);
173	  const curDay = parseInt(parts.day ?? "0", 10);
174	
175	  const firstDate = nextWeekdayDate(curYear, curMonth, curDay, weekday, true);
176	  const firstParsed = parseDateIso(firstDate);
177	  const firstDateObj = new Date(Date.UTC(firstParsed.year, firstParsed.month - 1, firstParsed.day));
178	
179	  const result: Array<string> = [];
180	  for (let i = 0; i < 8; i++) {
181	    const d = new Date(firstDateObj.getTime() + i * 7 * 86_400_000);
182	    result.push(formatDateIso(d.getUTCFullYear(), d.getUTCMonth() + 1, d.getUTCDate()));
183	  }
184	  return result;
185	};
