187	export const calculateRoundInstants = (
188	  targetDateStr: string,
189	  sendTime: SendTime,
190	  memberTimeZones: ReadonlyArray<string>,
191	  fallbackTimeZone: string,
192	  answerWindowDays: number,
193	): {
194	  readonly openInstant: number;
195	  readonly latestSendInstant: number;
196	  readonly closeInstant: number;
197	  readonly sends: ReadonlyArray<{ readonly timeZone: string; readonly sendAt: number }>;
198	} => {
199	  const { year, month, day } = parseDateIso(targetDateStr);
200	  const { hour, minute } = parseSendTime(sendTime);
201	
202	  const timeZonesToUse = memberTimeZones.length > 0 ? memberTimeZones : [fallbackTimeZone];
203	
204	  const sends = timeZonesToUse.map((tz) => ({
205	    timeZone: tz,
206	    sendAt: localToUtc(year, month, day, hour, minute, tz),
207	  }));
208	
209	  const sendTimes = sends.map((s) => s.sendAt);
210	  const openInstant = Math.min(...sendTimes);
211	  const latestSendInstant = Math.max(...sendTimes);
212	  const closeInstant = latestSendInstant + answerWindowDays * 24 * 3600_000;
213	
214	  return {
215	    openInstant,
216	    latestSendInstant,
217	    closeInstant,
218	    sends,
219	  };
220	};
