237	const addDays = (dateIso: string, days: number): string => {
238	  const { year, month, day } = parseDateIso(dateIso);
239	  const d = new Date(Date.UTC(year, month - 1, day) + days * 86_400_000);
240	  return formatDateIso(d.getUTCFullYear(), d.getUTCMonth() + 1, d.getUTCDate());
