243	const teamToday = (now: number, timeZone: string) => {
244	  const dtf = new Intl.DateTimeFormat("en-US", {
245	    timeZone,
246	    year: "numeric",
247	    month: "2-digit",
248	    day: "2-digit",
249	  });
250	  const parts: Record<string, string> = {};
251	  for (const p of dtf.formatToParts(new Date(now))) {
252	    parts[p.type] = p.value;
253	  }
254	  return {
255	    year: parseInt(parts.year ?? "0", 10),
256	    month: parseInt(parts.month ?? "0", 10),
257	    day: parseInt(parts.day ?? "0", 10),
258	  };
259	};
