261	export const nextRoundSlot = (input: RoundSlotInput): RoundSlot => {
262	  const slotOn = (plannedOpenDate: string): RoundSlot => ({
263	    plannedOpenDate,
264	    instants: calculateRoundInstants(
265	      plannedOpenDate,
266	      input.sendTime,
267	      input.memberTimeZones,
268	      input.teamTimeZone,
269	      input.answerWindowDays,
270	    ),
271	  });
272	
273	  const today = teamToday(input.now, input.teamTimeZone);
274	  let slot = slotOn(nextWeekdayDate(today.year, today.month, today.day, input.weekday, true));
275	  while (slot.instants.openInstant <= input.now || input.unavailableDates.has(slot.plannedOpenDate)) {
276	    slot = slotOn(addDays(slot.plannedOpenDate, 7));
277	  }
278	  return slot;
279	};
