281	export const calculateReminders = (
282	  sendInstant: number,
283	  answerWindowDays: number,
284	  remindersCount: number,
285	  closeInstant: number,
286	): ReadonlyArray<number> => {
287	  if (remindersCount <= 0) return [];
288	
289	  const candidates: Array<number> = [];
290	  if (answerWindowDays === 1) {
291	    candidates.push(sendInstant + 6 * 3600_000);
292	  } else if (remindersCount === 1) {
293	    candidates.push(sendInstant + (answerWindowDays - 1) * 24 * 3600_000);
294	  } else if (remindersCount === 2) {
295	    candidates.push(sendInstant + 1 * 24 * 3600_000);
296	    const dayWMinusOne = sendInstant + (answerWindowDays - 1) * 24 * 3600_000;
297	    if (dayWMinusOne !== candidates[0]) {
298	      candidates.push(dayWMinusOne);
299	    }
300	  }
301	
302	  const cutoff = closeInstant - 2 * 3600_000;
303	  return candidates.filter((time) => time < cutoff);
304	};
