306	export const calculateResultsReadyDeliveryTime = (nowMs: number, timeZone: string): number => {
307	  const dtf = new Intl.DateTimeFormat("en-US", {
308	    timeZone,
309	    year: "numeric",
310	    month: "2-digit",
311	    day: "2-digit",
312	    hour: "2-digit",
313	    minute: "2-digit",
314	    second: "2-digit",
315	    hour12: false,
316	  });
317	  const parts: Record<string, string> = {};
318	  for (const p of dtf.formatToParts(new Date(nowMs))) {
319	    parts[p.type] = p.value;
320	  }
321	  let h = parseInt(parts.hour ?? "0", 10);
322	  if (h === 24) h = 0;
323	  const year = parseInt(parts.year ?? "0", 10);
324	  const month = parseInt(parts.month ?? "0", 10);
325	  const day = parseInt(parts.day ?? "0", 10);
326	
327	  if (h >= 8 && h < 20) {
328	    return nowMs;
329	  }
330	
331	  if (h < 8) {
332	    return localToUtc(year, month, day, 8, 0, timeZone);
333	  }
334	
335	  const tomorrowUtc = Date.UTC(year, month - 1, day) + 86_400_000;
336	  const tomDate = new Date(tomorrowUtc);
337	  return localToUtc(
338	    tomDate.getUTCFullYear(),
339	    tomDate.getUTCMonth() + 1,
340	    tomDate.getUTCDate(),
341	    8,
342	    0,
343	    timeZone,
344	  );
345	};
