429	const B64_CHARS = "REDACTED";
430	
431	const base64url = (bytes: Uint8Array): string => {
432	  let result = "";
433	  const len = bytes.length;
434	  for (let i = 0; i < len; i += 3) {
435	    const b0 = bytes[i] ?? 0;
436	    const b1 = i + 1 < len ? (bytes[i + 1] ?? 0) : 0;
437	    const b2 = i + 2 < len ? (bytes[i + 2] ?? 0) : 0;
438	
439	    result += B64_CHARS[(b0 >> 2) & 0x3f];
440	    result += B64_CHARS[((b0 & 0x03) << 4) | ((b1 >> 4) & 0x0f)];
441	    if (i + 1 < len) {
442	      result += B64_CHARS[((b1 & 0x0f) << 2) | ((b2 >> 6) & 0x03)];
443	    }
444	    if (i + 2 < len) {
445	      result += B64_CHARS[b2 & 0x3f];
446	    }
447	  }
448	  return result;
449	};
