669	const roundSnapshot = (status: RoundStatus) =>
670	  roundMachine.resolveState({ value: status, context: { status, rejection: null } });
671	
672	const roundStep = (status: RoundStatus, command: RoundCommand) => {
673	  const snapshot = roundSnapshot(status);
674	  const [next, effects] = transition(roundMachine, snapshot, roundEvent(command));
675	  if (isUnhandled(snapshot, [next, effects])) {
676	    throw new Error("Round has no transition for " + command._tag + " in " + status);
677	  }
678	  return next.context;
679	};
680	
681	export const roundCommandRejection = (status: RoundStatus, command: RoundCommand): RoundRejection | null =>
682	  roundStep(status, command).rejection;
683	
684	export const roundStatusAfter = (status: RoundStatus, command: RoundCommand): RoundStatus =>
685	  roundStep(status, command).status;
