687	export const authorizeRoundAction = (
688	  directory: DirectoryState,
689	  actorId: PersonId,
690	  action: TeamAction,
691	  teamId: TeamId,
692	):
693	  | { readonly _tag: "Rejected"; readonly rejection: RoundRejection }
694	  | { readonly _tag: "Allowed"; readonly actor: Actor } => {
695	  const actor = actorOf(directory, actorId);
696	  if (actor._tag === "None" || !can(actor.value, action, { _tag: "Team", teamId })) {
697	    return reject({ _tag: "Forbidden" });
698	  }
699	  if (!directory.teams.some((team) => team.id === teamId)) {
700	    return reject({ _tag: "TeamNotFound" });
701	  }
702	  return { _tag: "Allowed", actor: actor.value };
703	};
