      parts[p.type] = p.value;
    }
    let h = parseInt(parts.hour ?? "0", 10);
    if (h === 24) h = 0;
    return {
      year: parseInt(parts.year ?? "0", 10),
      month: parseInt(parts.month ?? "0", 10),
      day: parseInt(parts.day ?? "0", 10),
