import { it, expect } from "@effect/vitest";
import * as Old from "./LifecycleOldScratch.ts";
import * as New from "./Lifecycle.ts";

const zones = ["Europe/Berlin", "America/New_York", "America/Los_Angeles", "Asia/Tokyo", "Australia/Lord_Howe", "Asia/Kathmandu", "Pacific/Chatham", "America/St_Johns", "UTC", "America/Sao_Paulo", "Africa/Casablanca", "Europe/Dublin", "America/Santiago", "Asia/Tehran"];
const weekdays = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"] as const;
const dayIso = (ms: number) => new Date(ms).toISOString().slice(0, 10);
let seed = 42;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const DAY = 86_400_000;
const span = Date.UTC(2025, 0, 1);

it("localToUtc matches the old implementation across wall-clock times", () => {
  let n = 0;
  const mismatches: string[] = [];
  for (const tz of zones) {
    const days: number[] = [];
    for (let d = 0; d < 1100; d++) days.push(span + d * DAY);
    for (const dayMs of days) {
      const d = new Date(dayMs);
      const y = d.getUTCFullYear(), m = d.getUTCMonth() + 1, dd = d.getUTCDate();
      const sample = dayMs < Date.UTC(2025, 2, 1) || dayMs > Date.UTC(2026, 11, 1)
        ? [0, 1, 2, 3, 23] : [0, 1, 2, 3, 4, 5, 22, 23];
      for (const h of sample) for (const mi of [0, 15, 30, 45]) {
        n++;
        const a = Old.localToUtc(y, m, dd, h, mi, tz);
        const b = New.localToUtc(y, m, dd, h, mi, tz);
        if (a !== b && mismatches.length < 20) mismatches.push(`${tz} ${y}-${m}-${dd} ${h}:${mi} old=${a} new=${b}`);
      }
    }
  }
  console.log("localToUtc cases", n, "mismatches", mismatches);
  expect(mismatches).toEqual([]);
});

it("results-ready, cadence and slot match the old implementation on random instants", () => {
  let n = 0;
  const mismatches: string[] = [];
  for (let i = 0; i < 20000; i++) {
    const now = span + Math.floor(rnd() * 3 * 365 * DAY);
    const tz = zones[i % zones.length]!;
    n++;
    const a = Old.calculateResultsReadyDeliveryTime(now, tz);
    const b = New.calculateResultsReadyDeliveryTime(now, tz);
    if (a !== b && mismatches.length < 20) mismatches.push(`ready ${tz} ${now} ${a} ${b}`);
    const wd = weekdays[i % 7]!;
    const ca = Old.nextEightWeeksCadenceDates(now, wd, tz).join();
    const cb = New.nextEightWeeksCadenceDates(now, wd, tz).join();
    if (ca !== cb && mismatches.length < 20) mismatches.push(`cadence ${tz} ${wd} ${now}`);
    const sendTime = (["06:00", "09:30", "14:45", "21:00", "00:00", "23:59"] as const)[i % 6]!;
    const input = {
      now,
      weekday: wd,
      sendTime: sendTime as never,
      teamTimeZone: tz,
      memberTimeZones: [zones[(i * 3) % zones.length]!, zones[(i * 5) % zones.length]!],
      answerWindowDays: 1 + (i % 4),
      unavailableDates: new Set<string>(i % 3 === 0 ? [dayIso(now + 7 * DAY)] : []),
    };
    const sa = JSON.stringify(Old.nextRoundSlot(input));
    const sb = JSON.stringify(New.nextRoundSlot(input));
    if (sa !== sb && mismatches.length < 20) mismatches.push(`slot ${sa} ${sb}`);
  }
  for (let t = 0; t < 2000; t++) {
    const y = 1990 + Math.floor(rnd() * 60), m = 1 + Math.floor(rnd() * 12), d = 1 + Math.floor(rnd() * 28);
    const wd = weekdays[t % 7]!;
    const inc = t % 2 === 0;
    n++;
    if (Old.nextWeekdayDate(y, m, d, wd, inc) !== New.nextWeekdayDate(y, m, d, wd, inc)) mismatches.push(`weekday ${y}-${m}-${d} ${wd}`);
  }
  console.log("random cases", n, "mismatches", mismatches);
  expect(mismatches).toEqual([]);
});
EOF
